Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean metRet;
        Common  metBuffer;
     
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(EcoResReleasedProductV2Entity, METInventTable))
        {
            metBuffer = METInventTable::find(this.ItemNumber, true);
        }

        if (metBuffer)
        {
            _dataSourceCtx.setBuffer(metBuffer);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
            this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
        }

        metRet = next insertEntityDataSource(_entityCtx, _dataSourceCtx);
    
        return metRet;
    }

    /// <summary>
    /// BUG185299_CB411_metreleasedproductsextendeddatafieldses
    /// </summary>
    public void postLoad()
    {
        next postload();

        METTariffItemCodeBase metTariffItemCodeBase = METTariffItemCodeBase::findRecId(this.METTariffItemCodeBaseRecid);
        if(metTariffItemCodeBase)
        {
            this.METTariffItem = metTariffItemCodeBase.TariffItem;
            this.METStatCode   = metTariffItemCodeBase.StatCode;
            this.METCustomExcise   = metTariffItemCodeBase.CustomsExcise;
        }
    }

    /// <summary>
    /// BUG185299_CB411_metreleasedproductsextendeddatafieldses
    /// </summary>
    /// <returns>ret</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = next validateWrite();

        if(this.METTariffItem && this.METStatCode)
        {
            METTariffItemCodeBase metTariffItemCodeBase = METTariffItemCodeBase::findbyTariffStatCode(this.METTariffItem, this.METStatCode);

            if (metTariffItemCodeBase)
            {
                this.METTariffItemCodeBaseRecid = metTariffItemCodeBase.RecId;
            }
            else
            {
                error("@MET:InvalidTariffItemAndStatcodeCombination");
                ret=false;
            }
        }
    
        return ret;
    }
